head.b:skin:
:root{--brand:#14523f;--brand2:#1f7a5c;--ink:#16211d;--sub:#5b6b65;--line:#e3ebe7;--bg:#f5f8f6;--card:#fff;--accent:#e8a33d}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font-family:'Pretendard',-apple-system,'Apple SD Gothic Neo','Noto Sans KR',sans-serif;font-size:17px;line-height:1.75;-webkit-font-smoothing:antialiased}
a{color:var(--brand2);text-decoration:none}
a:hover{text-decoration:underline}
.wrap{max-width:1120px;margin:0 auto;padding:0 20px}
.topbar{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.92);backdrop-filter:saturate(180%) blur(10px);border-bottom:1px solid var(--line)}
.topbar .wrap{display:flex;align-items:center;justify-content:space-between;height:64px;gap:16px}
.logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:19px;color:var(--ink)}
.logo:hover{text-decoration:none}
.logo-mark{width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:800}
.nav{display:flex;gap:22px;font-size:15px;font-weight:600}
.nav a{color:var(--sub)}
.nav a:hover{color:var(--brand);text-decoration:none}
.search-form{display:flex;align-items:center;background:var(--bg);border:1px solid var(--line);border-radius:999px;padding:4px 6px 4px 14px}
.search-form input{border:0;background:transparent;outline:0;font:inherit;font-size:14px;width:150px}
.search-form button{border:0;background:var(--brand);color:#fff;border-radius:999px;padding:6px 12px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}
.hero{background:radial-gradient(1200px 400px at 80% -10%,#2c8f6c 0,transparent 60%),linear-gradient(135deg,#0f3f31,#14523f 55%,#1a6a50);color:#fff;padding:72px 0 64px}
.hero .eyebrow{display:inline-block;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);border-radius:999px;padding:5px 14px;font-size:13px;font-weight:600;letter-spacing:.02em}
.hero h1{font-size:44px;line-height:1.25;margin:18px 0 14px;font-weight:800;letter-spacing:-.02em}
.hero h1 em{font-style:normal;color:#ffd58a}
.hero p.lead{font-size:18px;opacity:.9;max-width:620px;margin:0 0 28px}
.hero-cta{display:flex;gap:10px;flex-wrap:wrap}
.btn{display:inline-block;padding:12px 22px;border-radius:12px;font-weight:700;font-size:15px}
.btn:hover{text-decoration:none;transform:translateY(-1px)}
.btn-primary{background:#ffd58a;color:#173d30}
.btn-ghost{border:1px solid rgba(255,255,255,.4);color:#fff}
.trust{display:flex;gap:28px;flex-wrap:wrap;margin-top:40px;font-size:14px;opacity:.92}
.trust b{display:block;font-size:22px;font-weight:800}
.cats{margin-top:-34px;position:relative;z-index:2}
.cat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.cat{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:0 8px 24px rgba(20,82,63,.07);color:var(--ink);transition:.2s}
.cat:hover{text-decoration:none;transform:translateY(-3px);box-shadow:0 12px 30px rgba(20,82,63,.12)}
.cat .ic{font-size:26px}
.cat b{display:block;font-size:16px;margin-top:6px}
.cat span{font-size:13px;color:var(--sub)}
.section-head{display:flex;align-items:end;justify-content:space-between;margin:56px 0 18px}
.section-head h2{font-size:26px;margin:0;font-weight:800;letter-spacing:-.01em}
.section-head p{margin:2px 0 0;color:var(--sub);font-size:15px}
.post-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.card{background:var(--card);border:1px solid var(--line);border-radius:16px;overflow:hidden;display:flex;flex-direction:column;transition:.2s}
.card:hover{transform:translateY(-3px);box-shadow:0 14px 34px rgba(20,82,63,.10)}
.card-top{height:8px;background:linear-gradient(90deg,var(--brand),var(--brand2),var(--accent))}
.card-body{padding:20px 20px 18px;display:flex;flex-direction:column;flex:1}
.card .tag{align-self:flex-start;background:#e8f3ee;color:var(--brand);font-size:12px;font-weight:700;border-radius:999px;padding:3px 10px}
.card h3{font-size:19px;line-height:1.45;margin:12px 0 8px;font-weight:800}
.card h3 a{color:var(--ink)}
.card p{font-size:14.5px;color:var(--sub);margin:0 0 16px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.card .meta{margin-top:auto;display:flex;justify-content:space-between;font-size:13px;color:#8a9893}
.card .more{font-weight:700;color:var(--brand2)}
.pager{display:flex;justify-content:center;gap:10px;margin:34px 0 10px}
.pager a{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 18px;font-weight:700;font-size:14px}
.cta-band{margin:64px 0 0;background:var(--card);border:1px solid var(--line);border-radius:20px;padding:30px 32px;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}
.cta-band h3{margin:0 0 4px;font-size:21px}
.cta-band p{margin:0;color:var(--sub);font-size:15px}
.article-wrap{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:28px;margin:36px auto 0}
.article{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:40px 44px}
.crumb{font-size:13px;color:var(--sub);margin-bottom:10px}
.article h1{font-size:32px;line-height:1.35;margin:0 0 10px;font-weight:800;letter-spacing:-.02em}
.article .a-meta{font-size:14px;color:var(--sub);padding-bottom:18px;border-bottom:1px solid var(--line);margin-bottom:24px}
.post-body h2{font-size:23px;margin:40px 0 14px;padding:0 0 0 12px;border-left:5px solid var(--brand);line-height:1.4}
.post-body h3{font-size:19px;margin:28px 0 10px}
.post-body table{width:100%;border-collapse:collapse;margin:18px 0;font-size:15.5px;border-radius:12px;overflow:hidden}
.post-body th{background:#e8f3ee !important;color:var(--brand)}
.post-body th,.post-body td{border:1px solid var(--line) !important;padding:10px 12px !important}
.post-body blockquote{margin:20px 0;padding:14px 18px;background:#fff8ea;border-left:4px solid var(--accent);border-radius:0 10px 10px 0}
.post-body ul{padding-left:22px}
.post-body img{max-width:100%;height:auto;border-radius:12px}
.side .box{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px;position:sticky;top:84px}
.side h4{margin:0 0 10px;font-size:16px}
.side p{font-size:14px;color:var(--sub);margin:0 0 12px}
.side .links a{display:block;padding:8px 0;border-top:1px solid var(--line);font-size:14.5px;font-weight:600;color:var(--ink)}
.notice{font-size:13.5px;color:var(--sub);background:var(--bg);border-radius:12px;padding:14px 16px;margin-top:34px}
.footer{margin-top:80px;background:#0f2c23;color:#b9cac3;padding:48px 0 30px;font-size:14px}
.footer .cols{display:grid;grid-template-columns:2fr 1fr 1fr;gap:30px}
.footer b{color:#fff;font-size:16px}
.footer a{color:#d7e6e0;display:block;padding:3px 0}
.footer .copy{border-top:1px solid #23463a;margin-top:30px;padding-top:18px;font-size:13px}
@media (max-width:900px){.nav{display:none}.cat-grid{grid-template-columns:repeat(2,1fr)}.post-grid{grid-template-columns:1fr 1fr}.article-wrap{grid-template-columns:1fr}.side .box{position:static}}
@media (max-width:600px){body{font-size:16px}.hero{padding:48px 0 56px}.hero h1{font-size:31px}.search-form input{width:90px}.post-grid{grid-template-columns:1fr}.article{padding:26px 20px;border-radius:14px}.article h1{font-size:26px}.footer .cols{grid-template-columns:1fr}.trust{gap:18px}}
